import{_ as l,o as i,c as t,j as a,a as e,a5 as n}from"./chunks/framework.R-FQ1xZ2.js";const _=JSON.parse('{"title":"混合检索与重排","description":"稠密与稀疏两路怎么各自召回、分数怎么融合、重排器在哪个位置介入。","frontmatter":{"title":"混合检索与重排","description":"稠密与稀疏两路怎么各自召回、分数怎么融合、重排器在哪个位置介入。"},"headers":[],"relativePath":"diagrams/hybrid-retrieval-rerank.md","filePath":"diagrams/hybrid-retrieval-rerank.md","lastUpdated":null}'),o={name:"diagrams/hybrid-retrieval-rerank.md"};function s(d,r,c,h,f,u){return i(),t("div",null,[...r[0]||(r[0]=[a("h1",{id:"混合检索与重排",tabindex:"-1"},[e("混合检索与重排 "),a("a",{class:"header-anchor",href:"#混合检索与重排","aria-label":'Permalink to "混合检索与重排"'},"​")],-1),a("p",null,[a("span",{class:"fig-badge"},"数据流图"),e(),a("code",null,"dataflow")],-1),a("blockquote",null,[a("p",null,[a("strong",null,"一句话"),e("：稠密与稀疏两路怎么各自召回、分数怎么融合、重排器在哪个位置介入。")])],-1),a("div",{class:"fig-frame"},[a("iframe",{src:"/fig/hybrid-retrieval-rerank.html",title:"混合检索与重排",loading:"lazy",allowfullscreen:""})],-1),n('<p class="fig-actions"><a href="/fig/hybrid-retrieval-rerank.html" target="_blank" rel="noreferrer">在新窗口打开（可缩放 / 切换明暗主题 / 导出图片）</a></p><h2 id="怎么读这张图" tabindex="-1">怎么读这张图 <a class="header-anchor" href="#怎么读这张图" aria-label="Permalink to &quot;怎么读这张图&quot;">​</a></h2><ol><li>两路召回是并行的，各自拿 top-N，N 通常远大于最终要用的条数。</li><li>分数融合有两条路线：改分数（加权和，需要归一化）和改顺序（RRF，只用排名，对量纲不敏感）。RRF 更稳，因为它不需要假设两路分数可比。</li><li>重排器是 Cross-Encoder，把 query 和文档拼在一起过一遍模型，精度高但代价是 O(候选数) 次前向——这就是它慢的原因。</li><li>重排的候选数是一个纯粹的成本/收益权衡点，要能说出你的取值和依据。</li></ol><h2 id="面试口径" tabindex="-1">面试口径 <a class="header-anchor" href="#面试口径" aria-label="Permalink to &quot;面试口径&quot;">​</a></h2><ul><li>「为什么要混合检索？」——稀疏擅长精确词匹配与稀有词，稠密擅长语义泛化，两者失败模式不同，互补。</li><li>「RRF 的公式是什么？」——<code>score = Σ 1/(k + rank)</code>，k 通常取 60；只用排名所以不需要归一化。</li><li>「重排为什么不能直接替掉召回？」——Cross-Encoder 要对每个候选单独前向，没法对全库做，只能做精排。</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/learn/kb/l3-rag/">L3 RAG 与检索</a></li><li><a href="/learn/diagrams/rag-pipeline.html">RAG 端到端管线</a></li></ul>',7)])])}const p=l(o,[["render",s]]);export{_ as __pageData,p as default};
